```

/*
   Chess Tournament Pairing – minimal rated-vs-rated opponents
   Formula:  Let R = max(0, 2*X - 2*N).  Each remaining rated player after pairing with all unrated must face another rated player, so the minimal count of rated players whose opponent is also rated equals R.
*/
#include <stdio.h>

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;            // read number of test cases
    while (T--) {
        int N, X;
        scanf("%d %d", &N, &X);
        int answer = 0;
        int diff = 2*X - 2*N;                       // 2*(X - N)
        if (diff > 0) answer = diff;                // only positive part matters
        printf("%d\n", answer);
    }
    return 0;
}

