Below is a fully-working, minimal Chrome extension (Manifest V3) that saves the current page as an HTML file when the toolbar button is clicked.

File structure:
.
├── manifest.json
├── service_worker.js
└── icons/
    └── save-32.png

--- manifest.json ---
{
  "name": "Save Page HTML",
  "description": "One-click save of the current tab's HTML source.",
  "version": "1.0",
  "manifest_version": 3,
  "action": {
    "default_icon": {
      "32": "icons/save-32.png"
    },
    "default_title": "Save this page"
  },
  "permissions": ["activeTab", "downloads", "scripting"],
  "host_permissions": ["<all_urls>"],
  "background": {
    "service_worker": "service_worker.js"
  },
  "icons": {
    "32": "icons/save-32.png"
  }
}

--- service_worker.js ---
/* global chrome */
/*  Service-worker that injects a small content script into the active tab, grabs   */
/*  the page's HTML, and triggers a download as   YYYY-MM-DD_HH-MM-SS_hostname.html */

async function getPageHTML(tabId) {
  const [{ result }] = await chrome.scripting.executeScript({
    target: { tabId },
    func: () => document.documentElement.outerHTML
  });
  return result;
}

function sanitizeFilename(str) {
  return str.replace(/[^a-z0-9-_]/gi, '_');
}

chrome.action.onClicked.addListener(async (tab) => {
  try {
    const html = await getPageHTML(tab.id);
    const url = new URL(tab.url);
    const timestamp = new Date().toISOString().replace(/[:T]/g, '-').split('.')[0];
    const filename = `${timestamp}_${sanitizeFilename(url.hostname)}.html`;

    const blobUrl = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
    await chrome.downloads.download({ url: blobUrl, filename, saveAs: true });
  } catch (err) {
    console.error('Failed to save page:', err);
  }
});

/* Notes:
 * - Requires only minimal permissions (activeTab & downloads).
 * - Uses chrome.scripting instead of deprecated executeScript from the tab API.
