static inline void print_cpx_sample(int32_t val)
{
    int16_t re = (int16_t)( val & 0xFFFF );
    int16_t im = (int16_t)((val >> 16) & 0xFFFF);
    printf("(%6d,%6d) ", re, im);
}

/* -------------------------------------------------------------- */
/* Main routine:                                                  */
void print_rxdataF(const RU_t              *ru,
                   const NR_DL_FRAME_PARMS *fp)
{
    if (!ru || !fp) { fprintf(stderr,"print_rxdataF: NULL argument\n"); return; }
    if (!ru->common.rxdataF) { fprintf(stderr,"print_rxdataF: rxdataF not allocated\n"); return; }

    const uint32_t len_per_ant = NUMBER_RX_BUFFERS * fp->symbols_per_slot * fp->ofdm_symbol_size;

    for (uint32_t ant = 0; ant < ru->nb_rx; ++ant) {
        int32_t *buf = ru->common.rxdataF[ant];
        if (!buf) { fprintf(stderr,"print_rxdataF: antenna %u pointer is NULL\n", ant); continue; }

        printf("\n================ Antenna %u (%"PRIu32" samples) ================\n",
               ant, len_per_ant);

        for (uint32_t rb = 0; rb < NUMBER_RX_BUFFERS; ++rb) {
            for (uint32_t sym = 0; sym < fp->symbols_per_slot; ++sym) {
                uint32_t base = (rb * fp->symbols_per_slot + sym) * fp->ofdm_symbol_size;

                printf("[ant %u | buf %u | sym %u] :\n", ant, rb, sym);

                for (uint32_t sc = 0; sc < fp->ofdm_symbol_size; ++sc) {
                    print_cpx_sample(buf[base + sc]);
                    if ((sc & 0x7) == 0x7) printf("\n"); /* wrap every 8 sub-carriers */
