        self.sq = list('rnbqkbnrpppppppp................................PPPPPPPPRNBQKBNR')
        self.white_to_move = True
        self.castling = {'K':True,'Q':True,'k':True,'q':True}
        self.enpassant = -1
        self.halfmove = 0
        self.fullmove = 1
