                        moves.append(Move(sq,fwd+dir*8))
                # Captures
                for d in (-1,1):
                    tgt = fwd + d
                    if tgt in range(64):
                        if self.sq[tgt] != '.' and (self.sq[tgt].isupper()!=piece.isupper()):
                            if tgt//8 in (0,7):
                                for promo in 'qrbn': moves.append(Move(sq,tgt,promo))
                            else:
                                moves.append(Move(sq,tgt))
                        if tgt == self.enpassant:
