        self.sq[m.start]='.'
        # Pawn two-step sets en passant square
        if piece.lower()=='p' and abs(m.end-m.start)==16:
            self.enpassant = (m.start+m.end)//2
        # Update castling rights if king/rook moved or captured
        # …
        self.white_to_move = not self.white_to_move
        self.fullmove += (1 if not self.white_to_move else 0)

    def undo(self):
