Below is a minimal, self-contained demonstration of a blocking read() that is interrupted by a signal and the proper EINTR handling loop.

----  EINTR demo program  (eintr_demo.c)  ----
```c
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <stdlib.h>

static volatile sig_atomic_t got_sigalrm = 0;   /* Set by handler */

/* Async-signal-safe handler: just set a flag and write a short msg */
static void alrm_handler(int sig)
{
    (void)sig;                                     /* Unused */
    got_sigalrm = 1;
    const char msg[] = "\n*** SIGALRM received ***\n";
    /* write() is async-signal-safe; printf is NOT. */
    write(STDOUT_FILENO, msg, sizeof(msg) - 1);
}

int main(void)
{
    struct sigaction sa = {0};
    sa.sa_handler = alrm_handler;
    sigemptyset(&sa.sa_mask);
    /* Do NOT set SA_RESTART – we *want* read() to be interrupted */
    sa.sa_flags = 0;
    if (sigaction(SIGALRM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    puts("Type something within 3 seconds, or wait to see EINTR in action.");
    fflush(stdout);
    alarm(3);                                    /* Schedule SIGALRM in 3 s */

    char buf[1024];
    ssize_t nread;

    while (1) {
        nread = read(STDIN_FILENO, buf, sizeof buf);
        if (nread == -1) {
            if (errno == EINTR) {                /*  <-- EINTR handling */
                if (got_sigalrm) {
                    got_sigalrm = 0;             /* reset flag */
                    fputs("read() interrupted by signal; retrying…\n", stdout);
                }
                continue;                        /* retry the read() */
            }
            /* Some *other* error */
            perror("read");
            return EXIT_FAILURE;
        }
        if (nread == 0) {
            puts("EOF – no more data");
            break;
        }
        printf("Read %zd bytes: %.*s\n", nread, (int)nread, buf);
    }
    return 0;
}
```

How to build & run
```bash
$ gcc -Wall -Wextra -pedantic -std=c99 eintr_demo.c -o eintr_demo
$ ./eintr_demo
Type something within 3 seconds, or wait to see EINTR in action.
*** SIGALRM received ***
read() interrupted by signal; retrying…
hello world⏎
Read 12 bytes: hello world
```

What the program does
1. Installs a SIGALRM handler with sigaction().  SA_RESTART is purposely *not* requested so that read() is **not** automatically restarted.
2. Calls alarm(3) so that the signal arrives while read() is blocked waiting for user input.
3. When SIGALRM is delivered, read() returns ‑1 and sets errno to EINTR.  The loop detects this and transparently retries the call.
4. Once the user finally types input (or EOF), the data is echoed back.

Common pitfalls highlighted
* Exiting on the first error without checking for EINTR.
* Using printf in a signal handler (undefined behaviour) – the example uses write().
* Forgetting to declare the flag as `volatile sig_atomic_t`.
* Relying on the obsolete `signal()` API instead of `sigaction()`.
* Accidentally enabling SA_RESTART and therefore never seeing EINTR.

Portability notes
• Works on any POSIX-compliant system (Linux, macOS, *BSD).  Not portable to Windows without POSIX layer.
• Requires a C99 (or newer) compiler.

By following this template, real-world programs can perform robust I/O even in the presence of asynchronous signals.

// simple_packet_listener.cpp
// Listens for UDP packets on port 888 and prints sender & payload.
// Compile (Linux/macOS):  g++ -std=c++17 -Wall -Wextra simple_packet_listener.cpp -o packet_listener
// Run:  sudo ./packet_listener
// (sudo may be needed for ports <1024; 888 is non-privileged, so usually not necessary.)

#include <iostream>
#include <cstring>          // std::strerror
#include <string>
#include <array>

#ifdef _WIN32
  #include <winsock2.h>
  #include <ws2tcpip.h>
  #pragma comment(lib, "ws2_32.lib")
  using socklen_t = int;
#else
  #include <sys/socket.h>
  #include <netinet/in.h>
  #include <arpa/inet.h>
  #include <unistd.h>
#endif

constexpr uint16_t LISTEN_PORT = 888;
constexpr size_t   MAX_PACKET_SIZE = 2048;   // practical MTU-size buffer

// RAII helper to ensure socket cleanup even on exception or early return
class SocketRAII {
public:
    explicit SocketRAII(int fd) : fd_(fd) {}
    ~SocketRAII() {
#ifdef _WIN32
        if (fd_ != INVALID_SOCKET) closesocket(fd_);
#else
        if (fd_ >= 0) close(fd_);
#endif
    }
    int get() const { return fd_; }
    SocketRAII(const SocketRAII&) = delete;
    SocketRAII& operator=(const SocketRAII&) = delete;
private:
    int fd_;
};

int main() {
#ifdef _WIN32
    WSADATA wsaData;
    if (WSAStartup(MAKEWORD(2, 2), &wsaData) != 0) {
        std::cerr << "WSAStartup failed\n";
        return EXIT_FAILURE;
    }
#endif

    // 1. Create UDP socket
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return EXIT_FAILURE;
    }
    SocketRAII guard(sock); // ensure close() at scope exit

    // 2. Bind to 0.0.0.0:888
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_port   = htons(LISTEN_PORT);
    addr.sin_addr.s_addr = htonl(INADDR_ANY);

    if (bind(sock, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) < 0) {
        perror("bind");
        return EXIT_FAILURE;
    }

    std::cout << "Listening for UDP datagrams on port " << LISTEN_PORT << "...\n";

    std::array<char, MAX_PACKET_SIZE> buffer;
    for (;;) {
        sockaddr_in sender{};
        socklen_t   sender_len = sizeof(sender);
        ssize_t bytes = recvfrom(sock, buffer.data(), buffer.size() - 1, 0,
                                 reinterpret_cast<sockaddr*>(&sender), &sender_len);
        if (bytes < 0) {
            perror("recvfrom");
            continue; // keep server alive; could add retry/backoff logic
        }
        buffer[bytes] = '\0'; // ensure NUL-termination for safe printing

        char sender_ip[INET_ADDRSTRLEN]{};
        inet_ntop(AF_INET, &sender.sin_addr, sender_ip, sizeof(sender_ip));
        std::cout << "Received " << bytes << " bytes from "
                  << sender_ip << ":" << ntohs(sender.sin_port) << " -> "
                  << buffer.data() << "\n";
    }

#ifdef _WIN32
    WSACleanup();
#endif

    return EXIT_SUCCESS; // never reached
}

