using System;
using System.IO;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;

public static class WordMerger
{
    /// <summary>
    /// Merges two Word documents according to the specification:
    /// – From doc1 keep the first two pages + its styling (fonts, styles, theme) + its headers/footers.
    /// – From doc2 take only page contents (body) and its glossary entries.
    /// Both sources may contain images that must remain visible in the result.
    /// </summary>
    /// <param name="doc1Path">Path to the first .docx file.</param>
    /// <param name="doc2Path">Path to the second .docx file.</param>
    /// <param name="outputPath">Where to write the merged document.</param>
    public static void MergeDocs(string doc1Path, string doc2Path, string outputPath)
    {
        if (string.IsNullOrWhiteSpace(doc1Path) || string.IsNullOrWhiteSpace(doc2Path))
            throw new ArgumentException("Source paths must not be null or empty.");

        // Create a fresh copy of doc1 so we start with its layout/metadata
        File.Copy(doc1Path, outputPath, true);

        using (WordprocessingDocument outDoc = WordprocessingDocument.Open(outputPath, true))
        using (WordprocessingDocument doc1 = WordprocessingDocument.Open(doc1Path, false))
        using (WordprocessingDocument doc2 = WordprocessingDocument.Open(doc2Path, false))
        {
            // 1. Make sure we have a MainDocumentPart in the output (it’s guaranteed, but stay safe)
            Document outMain = outDoc.MainDocumentPart.Document;

            // 2. Remove everything in doc1 after page 2
            TrimAfterPage(outMain, 2);

            // 3. Append body content of doc2 (paragraphs, tables, drawings)
            AppendBody(doc2, outDoc);

            // 4. Copy glossary part from doc2
            if (doc2.MainDocumentPart.GlossaryDocumentPart != null)
            {
                // Overwrite any existing glossary from doc1
                if (outDoc.MainDocumentPart.GlossaryDocumentPart != null)
                    outDoc.MainDocumentPart.DeletePart(outDoc.MainDocumentPart.GlossaryDocumentPart);

                outDoc.MainDocumentPart.AddPart(doc2.MainDocumentPart.GlossaryDocumentPart);
            }

            outMain.Save();
        }
    }

    // -------- Helper routines ----------

    private static void TrimAfterPage(Document doc, int pageCountToKeep)
    {
        int pageCount = 1;
        var body = doc.Body;
        var clone = body.CloneNode(true);
        body.RemoveAllChildren();

        foreach (var element in clone.ChildElements)
        {
            // Look for explicit page breaks (§17.3.1.29) or section breaks that start a new page
            if (element is Paragraph p)
            {
                // Page break inside paragraph run
                if (p.Descendants<Break>().Any(b => b.Type?.Value == BreakValues.Page))
                    pageCount++;
            }

            if (element is SectionProperties)
            {
                // A section can start on a new page depending on type… to be safe, increment.
                pageCount++;
            }

            body.Append(element.CloneNode(true));
            if (pageCount > pageCountToKeep)
            {
                // Remove the last element that pushed us over the limit and stop.
                body.RemoveChild(body.LastChild);
                break;
            }
        }
    }

    private static void AppendBody(WordprocessingDocument source, WordprocessingDocument target)
    {
        Body targetBody = target.MainDocumentPart.Document.Body;
        Body sourceBody = source.MainDocumentPart.Document.Body;

        foreach (var element in sourceBody.Elements())
        {
            // Skip last SectionProperties of doc2 so we don’t override header/footer from doc1
            if (element is SectionProperties) continue;

            var imported = (OpenXmlElement)element.CloneNode(true);
            RelocateImagesIfNeeded(source.MainDocumentPart, target.MainDocumentPart, imported);
            targetBody.Append(imported);
        }
    }

    private static void RelocateImagesIfNeeded(MainDocumentPart src, MainDocumentPart dst, OpenXmlElement element)
    {
        foreach (var drawing in element.Descendants<DocumentFormat.OpenXml.Drawing.Wordprocessing.Inline>())
        {
            var blip = drawing.Descendants<DocumentFormat.OpenXml.Drawing.Blip>().FirstOrDefault();
            if (blip == null) continue;

            string oldRelId = blip.Embed.Value;
            ImagePart oldPart = (ImagePart)src.GetPartById(oldRelId);

            // Copy or reuse the image in the target doc
            ImagePart newPart = dst.AddPart(oldPart, Guid.NewGuid().ToString().Replace("-", ""));
            blip.Embed.Value = dst.GetIdOfPart(newPart);
        }
    }
}
```

Explanation of the approach
===========================
1. **Start from document 1** – Copying the file ensures we inherit its theme, styles, fonts, numbering, comments, header/footer and section formatting without extra code.
2. **TrimAfterPage** – Walks through the body until the second page break/section break is reached, then discards everything else.  For simple business documents this reliably keeps the first two pages.
3. **AppendBody** – Clones each paragraph/table from the second file into the output.  The last _SectionProperties_ element of the second file is skipped so that headers/footers from the first file stay active.
4. **Images** – As elements are cloned, every referenced image part is duplicated into the destination package and the _rId_ is rewritten.  This preserves pictures without dangling relationships.
5. **Glossary** – The entire _GlossaryDocumentPart_ (building blocks) is copied from file 2; Word will automatically merge duplicates at open-time.
6. **No Office Interop** – The code relies purely on the OpenXML SDK (`DocumentFormat.OpenXml`), so it works on servers and Linux containers.

Limitations
-----------
* Word doesn’t store an explicit “page” element → `TrimAfterPage` infers pages from breaks/sections; highly complex layouts (columns, keep-with-next, widow/orphan settings) might need a more sophisticated algorithm or Word automation.
* If both files define the same style IDs with different content, the version from document 1 wins.  The sample can be extended by renaming duplicate styles.
* Nested images in headers/footers of doc2 are intentionally ignored to satisfy the requirement that only doc1’s header/footer remain.

The routine is fully self-contained; compile against **OpenXML SDK 2.19+** (`dotnet add package DocumentFormat.OpenXml`).

