// Computes the n-th Fibonacci number modulo p using fast doubling in O(log n)
// Supports arbitrarily large n via BigInt (ES2020+)
function fibMod(n, p) {
  if (typeof n !== 'bigint' && typeof n !== 'number') throw new TypeError('n must be an integer');
  if (typeof p !== 'bigint' && typeof p !== 'number') throw new TypeError('p must be an integer');
  n = BigInt(n);
  p = BigInt(p);
  if (p <= 0n) throw new RangeError('modulus p must be positive');
  if (n < 0n) throw new RangeError('n must be non-negative');

  // Fast-doubling helper that returns [F(k), F(k+1)] modulo p
  function fd(k) {
    if (k === 0n) return [0n, 1n];
    const [a, b] = fd(k >> 1n);        // a = F(k/2), b = F(k/2 + 1)
    const c = (a * ((2n * b % p + p) - a + p)) % p;        // F(2m) = F(m) * [2*F(m+1) − F(m)]
    const d = (a * a + b * b) % p;                         // F(2m+1) = F(m)^2 + F(m+1)^2
    if ((k & 1n) === 0n) return [c, d];
    return [d, (c + d) % p];
  }
  return Number(fd(n)[0] % p); // cast to Number when safe; returns BigInt if > 2^53-1
}

