var _noise : OpenSimplexNoise
var _chunks                           : Dictionary   # key = Vector2i(x,z) ; value = Chunk (see below)
var _player                           : Node3D

# ====== Helper inner class ======
class Chunk:
    var pos                 : Vector2i          # chunk grid coord (x,z)
    var blocks              : PackedByteArray   # flat array size chunk_size*chunk_height*chunk_size
    var mesh_instance       : MeshInstance3D
    var dirty               : bool = true       # mark when blocks changed, triggers rebuild

func _ready() -> void:
    _init_noise()
    _player = get_tree().get_first_node_in_group("player")
    if _player == null:
        push_warning("No node in group 'player' found; chunks will not load relative to camera")
    _chunks = {}
    _update_visible_chunks(force = true)

func _physics_process(_delta: float) -> void:
    _update_visible_chunks()

# =================== Public API ===================
func add_block(global_pos: Vector3i, id: int) -> void:
    var chunk_coord = Vector2i(floor(global_pos.x / chunk_size), floor(global_pos.z / chunk_size))
    var chunk := _chunks.get(chunk_coord)
    if chunk == null:
        return
    var local = global_pos - Vector3i(chunk_coord.x * chunk_size, 0, chunk_coord.y * chunk_size)
    var index = _to_index(local)
    chunk.blocks[index] = id
    chunk.dirty = true

func remove_block(global_pos: Vector3i) -> void:
    add_block(global_pos, 0)

# ================ Internal Methods ================
func _init_noise():
    _noise = OpenSimplexNoise.new()
    _noise.seed = seed
    _noise.octaves = 4
    _noise.period = 64
    _noise.persistence = 0.5

func _update_visible_chunks(force := false) -> void:
    if _player == null:
        return
    var player_chunk = Vector2i(round(_player.global_position.x / chunk_size), round(_player.global_position.z / chunk_size))
    for x in range(player_chunk.x - view_distance_in_chunks, player_chunk.x + view_distance_in_chunks + 1):
        for z in range(player_chunk.y - view_distance_in_chunks, player_chunk.y + view_distance_in_chunks + 1):
            var key = Vector2i(x, z)
            if not _chunks.has(key):
                _create_chunk(key)
    # Optionally unload far chunks (omitted for brevity)
    _rebuild_dirty_chunks(force)

func _create_chunk(coord: Vector2i) -> void:
    var chunk = Chunk.new()
    chunk.pos = coord
    chunk.blocks = PackedByteArray() # pre-allocate
    chunk.blocks.resize(chunk_size * chunk_height * chunk_size)

    _generate_chunk_blocks(chunk)

    chunk.mesh_instance = MeshInstance3D.new()
    chunk.mesh_instance.mesh = ArrayMesh.new()
    chunk.mesh_instance.material_override = terrain_material
    chunk.mesh_instance.transform.origin = Vector3(coord.x * chunk_size * block_scale, 0, coord.y * chunk_size * block_scale)
    add_child(chunk.mesh_instance)

    _chunks[coord] = chunk

func _generate_chunk_blocks(chunk: Chunk) -> void:
    # Simple height-map terrain
    for x in range(chunk_size):
        for z in range(chunk_size):
            var world_x = chunk.pos.x * chunk_size + x
            var world_z = chunk.pos.y * chunk_size + z
            var height = int((_noise.get_noise_2d(world_x, world_z) * 0.5 + 0.5) * 50) + 40
            height = clamp(height, 1, chunk_height-1)
            for y in range(height):
                var idx = _to_index(Vector3i(x, y, z))
                # 1 = grass/dirt block id
                chunk.blocks[idx] = 1

func _rebuild_dirty_chunks(force := false):
    for chunk in _chunks.values():
        if force or chunk.dirty:
            _build_mesh_for_chunk(chunk)
            chunk.dirty = false

func _build_mesh_for_chunk(chunk: Chunk):
    var st = SurfaceTool.new()
    st.begin(Mesh.PRIMITIVE_TRIANGLES)
    var inv_scale = Vector3(block_scale, block_scale, block_scale)

    for x in range(chunk_size):
        for y in range(chunk_height):
            for z in range(chunk_size):
                var idx = _to_index(Vector3i(x, y, z))
                if chunk.blocks[idx] == 0:
                    continue # empty
                # Only add faces that are exposed
                for dir_idx in 6:
                    var n = Vector3i(x, y, z) + _DIRS[dir_idx]
                    if _is_air(chunk, n):
                        _push_face(st, Vector3i(x, y, z), dir_idx)
    chunk.mesh_instance.mesh = st.commit(chunk.mesh_instance.mesh)

# ===== Helper utilities =====
const _DIRS = [Vector3i( 0, 1, 0), Vector3i( 0,-1, 0), Vector3i( 1, 0, 0), Vector3i(-1, 0, 0), Vector3i( 0, 0, 1), Vector3i( 0, 0,-1)]
const _FACE_VERTS = [
    [Vector3(0,1,0), Vector3(1,1,0), Vector3(1,1,1), Vector3(0,1,1)],
    [Vector3(0,0,1), Vector3(1,0,1), Vector3(1,0,0), Vector3(0,0,0)],
    [Vector3(1,0,0), Vector3(1,0,1), Vector3(1,1,1), Vector3(1,1,0)],
    [Vector3(0,0,1), Vector3(0,0,0), Vector3(0,1,0), Vector3(0,1,1)],
    [Vector3(0,0,1), Vector3(1,0,1), Vector3(1,1,1), Vector3(0,1,1)],
    [Vector3(1,0,0), Vector3(0,0,0), Vector3(0,1,0), Vector3(1,1,0)]
]

func _push_face(st: SurfaceTool, pos: Vector3i, dir_idx: int):
    var base = (pos * block_scale).to_vector3()
    var verts = _FACE_VERTS[dir_idx]
    var uv_offset = Vector2(dir_idx % 3, dir_idx / 3)
    for i in 4:
        st.add_vertex(base + verts[i] * block_scale)
        st.add_uv((verts[i].xz + uv_offset) / 3)
    var off = st.get_vertex_count() - 4
    st.add_index(off)
    st.add_index(off+1)
    st.add_index(off+2)
    st.add_index(off)
    st.add_index(off+2)
    st.add_index(off+3)

func _to_index(pos: Vector3i) -> int:
    return pos.y * chunk_size * chunk_size + pos.z * chunk_size + pos.x

func _is_air(chunk: Chunk, local: Vector3i) -> bool:
    if local.x < 0 or local.z < 0 or local.y < 0 or local.x >= chunk_size or local.z >= chunk_size or local.y >= chunk_height:
        return true # treat outside chunk as air (neighbour check simplified)
    return chunk.blocks[_to_index(local)] == 0

# Optional: input handling to break/place blocks (simplified)
func _unhandled_input(event):
    if event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_LEFT:
        var space = get_world_3d().direct_space_state
        var ray_from = _player.global_transform.origin
        var ray_to = ray_from + _player.transform.basis.z * -5.0
        var result = space.intersect_ray(ray_from, ray_to)
        if result:
            remove_block(result.position.floor())

//---------------- Example of a strong answer ----------------
// Generates a sequence of 32-bit values where EXACTLY 5 bits change
// with respect to the previous value.

class transition_gen;
   // "curr" is randomized each cycle; "prev" is held from last cycle.
   rand logic [31:0] curr;
   logic        [31:0] prev;

   // ---------- Constraint block ----------
   constraint trans_c {
      // Hamming distance between prev and curr must be 5
      $countones(curr ^ prev) == 5;

      // (Optional) Avoid trivial repeats, i.e. no all-zero toggles
      // curr != prev; // redundant because countones==5 already guarantees it

      // Ensure the solver treats PREV as known before solving CURR
      solve prev before curr;
   }

   // After each successful randomize, update prev for next cycle.
   function void post_randomize();
      prev = curr;
   endfunction
endclass

// ------------------ Testbench snippet ------------------
module tb;
   transition_gen gen = new();
   int i;
   initial begin
      // Initialise previous value explicitly; could be any legal 32-bit value
      gen.prev = 32'hDEADBEEF;
      for (i = 0; i < 10; i++) begin
         if (!gen.randomize()) $error("Unsatisfied constraint");
         $display("Iteration %0d: curr = %h  (prev = %h)  ones(prev^curr) = %0d", 
                  i, gen.curr, gen.prev, $countones(gen.curr ^ gen.prev));
      end
   end
endmodule

// ---- Notes ----
// 1. $countones(<expr>) is IEEE-1800-2017 compliant; older tools may use $onehot_count or lack support—
//    fall back to explicit bit loop if necessary.
// 2. If the randomization ever fails (e.g., prev has X/Z), the testbench prints an error.
// 3. Because 5 << 32, the constraint is always solvable; no additional coverage constraints required.
// 4. Alternative portable solution without $countones():
//      int unsigned diff_cnt;
//      constraint diff_loop {
//         diff_cnt == 5;
//         foreach (curr[i]) diff_cnt -= (curr[i] ^ prev[i]);
//         diff_cnt == 0;
//      }
//    but $countones is far more compact and clearer.

(*---------------------------------------------------------------------*)
(*  dot_product.ml – OCaml + OpenGL 4.3 compute-shader dot product      *)
(*  Build (Linux + opam):                                              *)
(*  opam install glfw.3 gl bigarray                                    *)
(*  ocamlfind ocamlopt -linkpkg -package glfw3,gl,bigarray dot_product.ml -o dot_product *)
(*---------------------------------------------------------------------*)

open Bigarray
open Gl           (* raw OpenGL bindings from the „gl“ opam package *)
open Glfw         (* window/context bootstrap *)

(* --------------------------- Helpers -------------------------------- *)
let check_shader status name flag getter info_log =
  if status = Gl._FALSE then (
    Printf.eprintf "ERROR: %s failed\n%s\n" name (info_log ());
    exit 1)

let compile_compute_shader src =
  let sid = Gl.createShader Gl.COMPUTE_SHADER in
  Gl.shaderSource sid src;
  Gl.compileShader sid;
  let status = Gl.getShaderiv sid Gl.COMPILE_STATUS in
  check_shader status "Compute shader compilation" Gl.COMPILE_STATUS
    (fun () -> Gl.getShaderInfoLog sid);
  sid

let link_program sid =
  let pid = Gl.createProgram () in
  Gl.attachShader pid sid;
  Gl.linkProgram pid;
  let status = Gl.getProgramiv pid Gl.LINK_STATUS in
  check_shader status "Program linking" Gl.LINK_STATUS
    (fun () -> Gl.getProgramInfoLog pid);
  pid

(* ------------------------- GLSL Shader ------------------------------ *)
let compute_shader_src = {|#version 430
layout(local_size_x = 256) in;

layout(std430, binding = 0) readonly buffer VecA { float a[]; };
layout(std430, binding = 1) readonly buffer VecB { float b[]; };
layout(std430, binding = 2) writeonly buffer Res { float result[]; };

shared float cache[256];

void main() {
  uint gid = gl_GlobalInvocationID.x;
  cache[gl_LocalInvocationID.x] = a[gid] * b[gid];
  barrier();
  for (uint s = 128u; s > 0u; s >>= 1u) {
    if (gl_LocalInvocationID.x < s)
      cache[gl_LocalInvocationID.x] += cache[gl_LocalInvocationID.x + s];
    barrier();
  }
  if (gl_LocalInvocationID.x == 0u)
    atomicAdd(result[0], cache[0]);
}|}

(* --------------------------- Main ----------------------------------- *)
let () =
  (* 1. Init GLFW + OpenGL 4.3 context *)
  if not (Glfw.init ()) then failwith "Cannot init GLFW";
  Glfw.windowHint Glfw.CONTEXT_VERSION_MAJOR 4;
  Glfw.windowHint Glfw.CONTEXT_VERSION_MINOR 3;
  Glfw.windowHint Glfw.OPENGL_PROFILE Glfw.OPENGL_CORE_PROFILE;
  let win = Glfw.createWindow ~width:1 ~height:1 ~title:"headless" () |> Option.get in
  Glfw.makeContextCurrent (Some win);

  (* 2. Prepare data *)
  let n = 1024 in
  let vec_a = Array.init n (fun i -> float_of_int (i+1)) in
  let vec_b = Array.init n (fun i -> 1.0) in         (* dot product = n*(n+1)/2 *)
  let expected = (float_of_int n *. float_of_int (n+1)) /. 2.0 in

  (* Convert to bigarray of floats (32-bit) *)
  let ba_of_array arr =
    let ba = Bigarray.Array1.create Bigarray.float32 Bigarray.c_layout n in
    Array.iteri (fun i v -> Bigarray.Array1.set ba i v) arr; ba in
  let ba_a = ba_of_array vec_a and ba_b = ba_of_array vec_b in

  (* 3. Create SSBOs *)
  let make_ssbo binding ba =
    let buf = Gl.genBuffer () in
    Gl.bindBuffer Gl.SHADER_STORAGE_BUFFER buf;
    let size = (Bigarray.Array1.dim ba) * 4 in  (* float32 *)
    Gl.bufferData Gl.SHADER_STORAGE_BUFFER size (Some (Bigarray.array1_of_genarray (Obj.magic ba))) Gl.STATIC_DRAW;
    Gl.bindBufferBase Gl.SHADER_STORAGE_BUFFER binding buf;
    buf in
  let _ = make_ssbo 0 ba_a in
  let _ = make_ssbo 1 ba_b in
  (* result buffer: single float initialised to zero *)
  let res_buf = Gl.genBuffer () in
  Gl.bindBuffer Gl.SHADER_STORAGE_BUFFER res_buf;
  let zero = Bigarray.Array1.create Bigarray.float32 Bigarray.c_layout 1 in
  Gl.Array1.set zero 0 0.0;
  Gl.bufferData Gl.SHADER_STORAGE_BUFFER 4 (Some (Bigarray.array1_of_genarray (Obj.magic zero))) Gl.DYNAMIC_READ;
  Gl.bindBufferBase Gl.SHADER_STORAGE_BUFFER 2 res_buf;

  (* 4. Compile & link compute shader *)
  let shader_id = compile_compute_shader compute_shader_src in
  let prog_id = link_program shader_id in

  (* 5. Dispatch compute *)
  Gl.useProgram prog_id;
  let groups = (n + 255) / 256 in
  Gl.dispatchCompute groups 1 1;
  Gl.memoryBarrier Gl.SHADER_STORAGE_BARRIER_BIT;

  (* 6. Read back result *)
  Gl.bindBuffer Gl.SHADER_STORAGE_BUFFER res_buf;
  let ptr = Gl.mapBufferRange Gl.SHADER_STORAGE_BUFFER 0 4 Gl.MAP_READ_BIT in
  let res = Bigarray.(Array1.get (array1_of_genarray (Obj.magic ptr)) 0) in
  Printf.printf "GPU dot product = %f (expected %f)\n" res expected;
  Gl.unmapBuffer Gl.SHADER_STORAGE_BUFFER;

  (* 7. Cleanup *)
  Gl.deleteProgram prog_id;
  Gl.deleteShader shader_id;
  Glfw.destroyWindow win; Glfw.terminate ()

// =========================
// Vertex shader (fullscreen quad)
// =========================
#version 330 core
layout(location = 0) in vec2 aPosition;      // –1..1 full-screen quad
out vec2 vUV;                                // Normalised 0..1 fragment coords
void main()
{
    vUV = (aPosition + 1.0) * 0.5;           // map –1..1 → 0..1
    gl_Position = vec4(aPosition, 0.0, 1.0); // pass straight through
}

// =========================
// Fragment shader (old-school ray-caster)
// =========================
#version 330 core
in  vec2 vUV;
out vec4 fragColor;

// ---------- Uniform inputs ----------
uniform sampler2D uMap;        // R channel = tile id (0 = empty)
uniform sampler2D uAtlas;      // Horizontal strip of 64×64 wall textures

uniform vec2  uPlayerPos;      // world units (float for sub-tile)
uniform vec2  uPlayerDir;      // normalised direction
uniform vec2  uCameraPlane;    // 90° plane (perp to dir) that scales FOV

uniform float uScreenWidth;    // pixels
uniform float uScreenHeight;   // pixels
const  int   MAX_STEPS = 64;   // hard stop to keep GPU happy

// Utility: fetch map value with bounds test
int mapValue(ivec2 m)
{
    // texelFetch uses integer coords → perfect for grid look-up
    if (m.x < 0 || m.y < 0 || m.x >= textureSize(uMap, 0).x || m.y >= textureSize(uMap, 0).y)
        return 1;                        // treat outside map as solid wall
    return int(texture(uMap, (vec2(m) + 0.5) / vec2(textureSize(uMap,0))).r * 255.0 + 0.5);
}

void main()
{
    //------------------------------------
    // 1) Compute ray direction for this column
    //------------------------------------
    float cameraX = 2.0 * gl_FragCoord.x / uScreenWidth - 1.0;  // –1 .. 1
    vec2  rayDir  = uPlayerDir + uCameraPlane * cameraX;

    //------------------------------------
    // 2) Prepare DDA variables
    //------------------------------------
    ivec2 mapPos  = ivec2(floor(uPlayerPos));
    vec2  delta   = abs(vec2(1.0) / rayDir);   // length from one x-side to next x-side, etc.

    ivec2 step;
    vec2  sideDist;
    if (rayDir.x < 0.0) { step.x = -1; sideDist.x = (uPlayerPos.x - float(mapPos.x)) * delta.x; }
    else                { step.x =  1; sideDist.x = (float(mapPos.x + 1) - uPlayerPos.x) * delta.x; }
    if (rayDir.y < 0.0) { step.y = -1; sideDist.y = (uPlayerPos.y - float(mapPos.y)) * delta.y; }
    else                { step.y =  1; sideDist.y = (float(mapPos.y + 1) - uPlayerPos.y) * delta.y; }

    //------------------------------------
    // 3) Walk the grid (DDA)
    //------------------------------------
    int side = 0;     // 0 = x-side, 1 = y-side
    int tile = 0;
    for (int i = 0; i < MAX_STEPS; ++i)
    {
        if (sideDist.x < sideDist.y) {
            sideDist.x += delta.x; mapPos.x += step.x; side = 0; }
        else                       {
            sideDist.y += delta.y; mapPos.y += step.y; side = 1; }

        tile = mapValue(mapPos);
        if (tile != 0) break;                       // hit non-empty cell
    }

    //------------------------------------
    // 4) No wall: render sky/floor gradient
    //------------------------------------
    if (tile == 0) {
        float t = vUV.y;
        fragColor = mix(vec4(0.5,0.7,1.0,1.0), vec4(0.2,0.2,0.2,1.0), t);
        return;
    }

    //------------------------------------
    // 5) Distance to wall (perpendicular to screen to remove fisheye)
    //------------------------------------
    float perpDist = (side == 0)
        ? (float(mapPos.x) - uPlayerPos.x + (1.0 - float(step.x)) * 0.5) / rayDir.x
        : (float(mapPos.y) - uPlayerPos.y + (1.0 - float(step.y)) * 0.5) / rayDir.y;

    //------------------------------------
    // 6) Compute size of slice that will be drawn for this column
    //------------------------------------
    float lineH   = uScreenHeight / perpDist; // classic formula
    float drawBeg = -lineH * 0.5 + uScreenHeight * 0.5;
    float drawEnd =  lineH * 0.5 + uScreenHeight * 0.5;

    //------------------------------------
    // 7) Pixels above / below slice → sky / floor
    //------------------------------------
    if (gl_FragCoord.y < drawBeg) {
        fragColor = vec4(0.5,0.7,1.0,1.0);   // sky blue
        return;
    }
    if (gl_FragCoord.y > drawEnd) {
        fragColor = vec4(0.25,0.25,0.25,1.0); // dark floor
        return;
    }

    //------------------------------------
    // 8) Sample wall texture
    //------------------------------------
    float hitPoint = (side == 0)
        ? (uPlayerPos.y + perpDist * rayDir.y)
        : (uPlayerPos.x + perpDist * rayDir.x);
    float texX = fract(hitPoint);                    // column on wall 0..1
    // Flip horizontal texture when hitting from right/upper side to match Wolf3D look
    if ((side == 0 && rayDir.x > 0.0) || (side == 1 && rayDir.y < 0.0))
        texX = 1.0 - texX;

    float texY = (gl_FragCoord.y - drawBeg) / lineH; // vertical coordinate 0..1

    // Atlas layout: textures sit side-by-side, id 1..N; each 64px wide
    vec2 atlasSize = vec2(textureSize(uAtlas,0));
    float tilesInAtlas = atlasSize.x / 64.0;
    vec2 texCoord = vec2((texX + float(tile - 1)) / tilesInAtlas, texY);
    vec4 color = texture(uAtlas, texCoord);

    // Darken y-side for depth cue like original games
    if (side == 1) color.rgb *= 0.7;

    fragColor = color;
}

Below is a step-by-step guide for an absolute beginner on reading a CSV file in JavaScript. I cover both "Node.js on your computer" and "in a web browser" so you can pick whichever applies.

──────────────────────────────────
PART A. Reading a CSV file with Node.js (local computer)
──────────────────────────────────
1) Install Node.js
   • Go to https://nodejs.org and download the LTS version (e.g. v20.x as of June 2024).
   • During installation, keep all default settings.
   • After it finishes, open a terminal/command prompt and type:
        node -v
     You should see something like `v20.11.1`.

2) Create a new folder for the mini-project, e.g. `csv-demo`, and put a sample file `people.csv` inside it:
   ```csv
   first_name,last_name,age
   Ada,Lovelace,36
   Grace,Hopper,85
   Alan,Turing,41
   ```

3) Initialise the project and install a CSV parsing library:
   ```bash
   cd csv-demo
   npm init -y         # creates a package.json file
   npm install csv-parser  # <--  tiny, popular library (~3 M downloads/week)
   ```

4) Create `readCsv.js` with the following content (fully commented):
   ```js
   // 1. Bring the built-in "fs" module for reading files and the third-party
   //    "csv-parser" module we just installed.
   const fs = require('fs');
   const csv = require('csv-parser');

   // 2. Create an empty array to collect each row so we can use it later.
   const results = [];

   // 3. fs.createReadStream opens the file as a stream (efficient for big files).
   //    We pipe (connect) that stream into the csv() parser.
   fs.createReadStream('people.csv')
     .pipe(csv())            // parses each line into a JS object
     .on('data', (data) => results.push(data))   // fires for every row
     .on('end', () => {
       // 4. When the stream ends, print the result or do whatever you need.
       console.log('CSV content as JavaScript objects:');
       console.table(results);
     })
     .on('error', (err) => {
       // 5. A little error-handling never hurts.
       console.error('Something went wrong:', err.message);
     });
   ```

5) Run it:
   ```bash
   node readCsv.js
   ```
   Expected output:
   ```text
   ┌─────────┬────────────┬───────────┬─────┐
   │ (index) │ first_name │ last_name │ age │
   ├─────────┼────────────┼───────────┼─────┤
   │    0    │   'Ada'    │ 'Lovelace'│ '36'│
   │    1    │  'Grace'   │ 'Hopper'  │ '85'│
   │    2    │   'Alan'   │ 'Turing'  │ '41'│
   └─────────┴────────────┴───────────┴─────┘
   ```

6) What if you don’t want external libraries? You could use Node’s built-in
   `readline` and `String.split(',')`, but that breaks on quoted commas, so using
   a tested library is safest.

──────────────────────────────────
PART B. Reading a CSV file in the Browser
──────────────────────────────────
1) Choose a lightweight parser: Papa Parse (no build tools required).  Add this
   inside your HTML <head>:
   ```html
   <script src="https://cdn.jsdelivr.net/npm/papaparse@5.4.3/papaparse.min.js"></script>
   ```

2) Provide an <input type="file"> so the user can choose a CSV from disk:
   ```html
   <input id="fileSelect" type="file" accept=".csv" />
   <pre id="output"></pre>
   <script>
     document.getElementById('fileSelect').addEventListener('change', function (evt) {
       const file = evt.target.files[0];
       if (!file) return;

       Papa.parse(file, {
         header: true,       // use first row as keys
         skipEmptyLines: true,
         complete: function (results) {
           // results.data is an array of objects
           document.getElementById('output').textContent = JSON.stringify(results.data, null, 2);
         },
         error: function (err) {
           alert('Trouble parsing file:' + err.message);
         }
       });
     });
   </script>
   ```

3) Open the HTML page in your browser, select the same `people.csv`, and you will
   see nicely formatted JSON in the <pre> element.

──────────────────────────────────
Common Pitfalls & Tips
──────────────────────────────────
• "Cannot find module 'csv-parser'": Run `npm install csv-parser` in the correct folder, or check your `package.json`.
• File-path errors: `fs.createReadStream('people.csv')` is relative to the script’s working directory. Use an absolute path or `path.join(__dirname, 'people.csv')` for safety.
• Large files: Streaming (as shown) keeps memory low. Reading the entire file with `fs.readFileSync` can crash on 1 GB+ CSVs.
• Browser security: Browsers block direct disk access for security reasons; you need user-selected File or fetch from a URL with CORS enabled.

You now have two well-tested ways to read CSV in JavaScript—one for server-side scripts, one for browser apps.

/**
 * extractTextFromDocument – return all visible text from a DOM Document.
 * @param {Document} doc  A valid DOM Document (e.g., window.document or JSDOM document).
 * @returns {string}      Concatenated textual content with reasonable line breaks.
 * @throws {TypeError}    If the argument is not a Document or has no body.
 */
function extractTextFromDocument(doc) {
  if (!doc || typeof doc !== "object" || !doc.body) {
    throw new TypeError("Invalid or missing Document provided to extractTextFromDocument");
  }

  // Elements whose text should be ignored entirely
  const IGNORED = new Set([
    "SCRIPT",
    "STYLE",
    "NOSCRIPT",
    "TEMPLATE",
    "META",
    "HEAD",
    "TITLE"
  ]);

  // Recursively walk the DOM tree collecting visible text nodes
  function walk(node) {
    switch (node.nodeType) {
      case Node.TEXT_NODE:
        return node.nodeValue.trim();

      case Node.ELEMENT_NODE: {
        if (IGNORED.has(node.tagName)) return "";

        let out = "";
        for (const child of node.childNodes) {
          const childText = walk(child);
          if (childText) {
            // Add a line break between logical block-level elements
            if (out && /^(P|DIV|LI|SECTION|ARTICLE|HEADER|FOOTER|NAV|BR|TR)$/i.test(node.tagName)) {
              out += "
";
            }
            out += childText + " ";
          }
        }
        return out.trim();
      }
      default:
        return ""; // Ignore comments, processing instructions, etc.
    }
  }

  // Post-process to collapse excessive whitespace/newlines
  return walk(doc.body)
    .replace(/\s+
/g, "
")
    .replace(/
{2,}/g, "

")
    .trim();
}

