// file: client/src/App.jsx
import { useEffect, useState } from "react";
import axios from "axios";

const api = axios.create({ baseURL: "http://localhost:5000" });

export default function App() {
  const [todos, setTodos] = useState([]);
  const [desc, setDesc] = useState("");

  const fetchTodos = async () => {
    const { data } = await api.get("/todos");
    setTodos(data);
  };

  useEffect(() => {
    fetchTodos();
  }, []);

  const addTodo = async (e) => {
    e.preventDefault();
    if (!desc.trim()) return;
    await api.post("/todos", { description: desc });
    setDesc("");
    fetchTodos();
  };

  const deleteTodo = async (id) => {
    await api.delete(`/todos/${id}`);
    setTodos(todos.filter((t) => t.todo_id !== id));
  };

  const updateTodo = async (id) => {
    const newDesc = prompt("Edit description:", todos.find((t) => t.todo_id === id).description);
    if (newDesc !== null) {
      await api.put(`/todos/${id}`, { description: newDesc });
      fetchTodos();
    }
  };

  return (
    <div style={{ maxWidth: 400, margin: "2rem auto", fontFamily: "sans-serif" }}>
      <h1>📝 PERN To-Do</h1>
      <form onSubmit={addTodo} style={{ marginBottom: "1rem" }}>
        <input
          value={desc}
          onChange={(e) => setDesc(e.target.value)}
          placeholder="Enter task"
          style={{ width: "70%" }}
        />
        <button>Add</button>
      </form>
      <ul>
        {todos.map((todo) => (
          <li key={todo.todo_id} style={{ marginBottom: "0.5rem" }}>
            {todo.description}
            <button onClick={() => updateTodo(todo.todo_id)} style={{ marginLeft: 8 }}>✏️</button>
            <button onClick={() => deleteTodo(todo.todo_id)} style={{ marginLeft: 4 }}>🗑️</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

