    data_t acc = b1[r];
    mult_loop: for (int c = 0; c < IMG_SIZE; ++c) {
#pragma HLS UNROLL factor=16   // 16-pixel wide MAC
      acc += in[c] * W1[r][c];
    }
    // ReLU activation
    out[r] = (acc > 0) ? acc : (data_t)0;
  }
}

void dense_2(data_t out[OUTPUT_SIZE], const data_t in[HIDDEN_SIZE]) {
#pragma HLS INLINE off
#pragma HLS ARRAY_PARTITION variable=W2 complete dim=2
#pragma HLS PIPELINE II=1
  dense2_loop: for (int r = 0; r < OUTPUT_SIZE; ++r) {
    data_t acc = b2[r];
    mult2_loop: for (int c = 0; c < HIDDEN_SIZE; ++c) {
#pragma HLS UNROLL factor=16
      acc += in[c] * W2[r][c];
    }
    out[r] = acc; // raw logits
  }
}

// Softmax (stream friendly, no division by exp sum until end)
void softmax(data_t in[OUTPUT_SIZE], data_t &pred, uint8_t &digit) {
#pragma HLS PIPELINE II=1
  data_t max_logit = in[0];
  find_max: for (int i = 1; i < OUTPUT_SIZE; ++i)
    if (in[i] > max_logit) max_logit = in[i];

  data_t sum = 0;
  exp_loop: for (int i = 0; i < OUTPUT_SIZE; ++i) {
#pragma HLS UNROLL
    in[i] = hls::exp(in[i] - max_logit);
    sum += in[i];
  }
  data_t inv_sum = 1 / sum;
  argmax_loop: for (int i = 0; i < OUTPUT_SIZE; ++i) {
#pragma HLS UNROLL
    data_t p = in[i] * inv_sum;
    if (p > pred) { pred = p; digit = i; }
  }
}

