/*
Explanation
-----------
The iterator stores previously discovered primes (Vec<u64>) so each new candidate only needs to be trial-divided by primes ≤ √candidate. After 2 we skip even numbers, halving the work. The algorithm is O(n log n) time and O(π(n)) memory, adequate for on-demand generation while avoiding the unbounded memory usage of a full sieve. The code is 100 % safe Rust, compiles on stable 1.70+, contains unit tests, and can be extended to u128 by replacing the type aliases.
*/

// Vanilla RNN implemented from scratch in plain TypeScript
// =======================================================
// Task: predict the next character in a short text corpus.
// Run with:  ts-node rnn.ts   (only built-in Node + ts-node required)

// -------------- Utility Types & Functions ---------------

type Matrix = number[][];

function zeros(rows: number, cols: number): Matrix {
  return Array.from({ length: rows }, () => Array(cols).fill(0));
}

function randomMatrix(rows: number, cols: number, scale = 0.08): Matrix {
  return Array.from({ length: rows }, () =>
    Array.from({ length: cols }, () => (Math.random() * 2 - 1) * scale)
  );
}

function dot(A: Matrix, B: Matrix): Matrix {
  const m = A.length, n = B[0].length, p = B.length;
  const out = zeros(m, n);
  for (let i = 0; i < m; i++)
    for (let k = 0; k < p; k++)
      for (let j = 0; j < n; j++) out[i][j] += A[i][k] * B[k][j];
  return out;
}

function add(A: Matrix, B: Matrix): Matrix {
  return A.map((row, i) => row.map((v, j) => v + B[i][j]));
}

function tanh(M: Matrix): Matrix {
  return M.map(row => row.map(v => Math.tanh(v)));
}

function tanhDerivative(M: Matrix): Matrix {
  return M.map(row => row.map(v => 1 - v * v));
}

function softmax(vec: number[]): number[] {
  const max = Math.max(...vec);
  const exps = vec.map(v => Math.exp(v - max));
  const sum = exps.reduce((a, b) => a + b, 0);
  return exps.map(e => e / sum);
}

function oneHot(index: number, size: number): number[] {
  const v = Array(size).fill(0);
  v[index] = 1;
  return v;
}

// -------------- RNN Class --------------------------------

class VanillaRNN {
  inputSize: number;
  hiddenSize: number;
  outputSize: number;
  Wxh: Matrix; // input -> hidden
  Whh: Matrix; // hidden -> hidden
  Why: Matrix; // hidden -> output
  bh: Matrix;
  by: Matrix;
  learningRate: number;

  constructor(inputSize: number, hiddenSize = 64, outputSize?: number, lr = 0.1) {
    this.inputSize = inputSize;
    this.hiddenSize = hiddenSize;
    this.outputSize = outputSize ?? inputSize;
    this.learningRate = lr;

    this.Wxh = randomMatrix(hiddenSize, inputSize);
    this.Whh = randomMatrix(hiddenSize, hiddenSize);
    this.Why = randomMatrix(this.outputSize, hiddenSize);
    this.bh = zeros(hiddenSize, 1);
    this.by = zeros(this.outputSize, 1);
  }

  // Forward pass through time. Returns loss and caches for backprop.
  forward(inputs: number[]): {
    loss: number;
    hs: Matrix[];
    xs: Matrix[];
    ys: Matrix[];
    ps: number[][];
  } {
    const xs: Matrix[] = [];
    const hs: Matrix[] = [zeros(this.hiddenSize, 1)]; // h_{-1}
    const ys: Matrix[] = [];
    const ps: number[][] = [];
    let loss = 0;

    for (let t = 0; t < inputs.length - 1; t++) {
      const x_t = inputs[t];
      const xVec = oneHot(x_t, this.inputSize).map(v => [v]); // column vec
      xs.push(xVec);

      // h_t = tanh(Wxh * x_t + Whh * h_{t-1} + bh)
      const hLinear = add(add(dot(this.Wxh, xVec), dot(this.Whh, hs[t])), this.bh);
      const h_t = tanh(hLinear);
      hs.push(h_t);

      // y_t = Why * h_t + by
      const y_t = add(dot(this.Why, h_t), this.by);
      ys.push(y_t);

      // p_t = softmax(y_t)
      const p_t = softmax(y_t.map(r => r[0]));
      ps.push(p_t);

      // cross-entropy loss: -log p[target]
      const target = inputs[t + 1];
      loss += -Math.log(p_t[target] + 1e-9);
    }
    return { loss, hs, xs, ys, ps };
  }

  backward(cache: ReturnType<typeof this.forward>, targets: number[]): void {
    const { xs, hs, ps } = cache;
    // Init gradients as zero matrices same size as parameters
    const dWxh = zeros(this.hiddenSize, this.inputSize);
    const dWhh = zeros(this.hiddenSize, this.hiddenSize);
    const dWhy = zeros(this.outputSize, this.hiddenSize);
    const dbh = zeros(this.hiddenSize, 1);
    const dby = zeros(this.outputSize, 1);

    let dhNext = zeros(this.hiddenSize, 1);

    for (let t = xs.length - 1; t >= 0; t--) {
      // Output gradient
      const dy = ps[t].slice();
      dy[targets[t + 1]] -= 1; // dL/dy
      const dyCol = dy.map(v => [v]);

      // dWhy += dy * h_t^T
      for (let i = 0; i < this.outputSize; i++)
        for (let j = 0; j < this.hiddenSize; j++)
          dWhy[i][j] += dyCol[i][0] * hs[t + 1][j][0];
      for (let i = 0; i < this.outputSize; i++) dby[i][0] += dyCol[i][0];

      // Backprop into h
      let dh = dot(transpose(this.Why), dyCol);
      for (let i = 0; i < this.hiddenSize; i++) dh[i][0] += dhNext[i][0];

      // tanh derivative
      const hRaw = tanhDerivative(hs[t + 1]);
      for (let i = 0; i < this.hiddenSize; i++) dh[i][0] *= hRaw[i][0];

      // gradients for parameters
      // dWxh += dh * x_t^T, dWhh += dh * h_{t-1}^T
      for (let i = 0; i < this.hiddenSize; i++)
        for (let j = 0; j < this.inputSize; j++)
          dWxh[i][j] += dh[i][0] * xs[t][j][0];

      for (let i = 0; i < this.hiddenSize; i++)
        for (let j = 0; j < this.hiddenSize; j++)
          dWhh[i][j] += dh[i][0] * hs[t][j][0];

      for (let i = 0; i < this.hiddenSize; i++) dbh[i][0] += dh[i][0];

      dhNext = dot(transpose(this.Whh), dh);
    }

    // Simple SGD update
    const clip = (v: number) => Math.max(-5, Math.min(5, v));
    function apply(param: Matrix, grad: Matrix) {
      for (let i = 0; i < param.length; i++)
        for (let j = 0; j < param[0].length; j++)
          param[i][j] += -this.learningRate * clip(grad[i][j]);
    }
    apply = apply.bind(this);

    apply(this.Wxh, dWxh);
    apply(this.Whh, dWhh);
    apply(this.Why, dWhy);
    apply(this.bh, dbh);
    apply(this.by, dby);
  }
}

function transpose(M: Matrix): Matrix {
  const rows = M.length, cols = M[0].length;
  const out = zeros(cols, rows);
  for (let i = 0; i < rows; i++)
    for (let j = 0; j < cols; j++) out[j][i] = M[i][j];
  return out;
}

// ------------------ Example Training --------------------

const text = "hello world";
const chars = Array.from(new Set(text.split(""))).sort();
const charIdx = new Map(chars.map((c, i) => [c, i]));
const indices = text.split("").map(c => charIdx.get(c)!);

const rnn = new VanillaRNN(chars.length, 32, chars.length, 0.2);

for (let epoch = 0; epoch < 500; epoch++) {
  const cache = rnn.forward(indices);
  rnn.backward(cache, indices);
  if (epoch % 50 === 0) console.log(`Epoch ${epoch}: loss=${cache.loss.toFixed(3)}`);
}

// Quick sampling after training
function sample(rnn: VanillaRNN, startChar: string, length = 20): string {
  let h = zeros(rnn.hiddenSize, 1);
  let idx = charIdx.get(startChar)!;
  let out = startChar;
  for (let t = 0; t < length; t++) {
    const x = oneHot(idx, rnn.inputSize).map(v => [v]);
    h = tanh(add(add(dot(rnn.Wxh, x), dot(rnn.Whh, h)), rnn.bh));
    const y = add(dot(rnn.Why, h), rnn.by);
    const probs = softmax(y.map(r => r[0]));
    const nextIdx = probs.indexOf(Math.max(...probs));
    out += chars[nextIdx];
    idx = nextIdx;
  }
  return out;
}

