// composables/useSession.ts
import { useQuery } from '@tanstack/vue-query'
import axios from 'axios'
import { useSessionStore } from '@/stores/session'

// Re-usable composition function that fetches the session and syncs it to Pinia
export function useSession () {
  const sessionStore = useSessionStore()

  /**
   * Axios GET → /get_session
   *  - Returns the raw server payload, e.g.
   *    { id: 42, email: 'alice@example.com', role: 'admin', lastSeen: '2023-10-12T09:17:00Z' }
   */
  const fetchSession = async () => {
    const { data } = await axios.get('/get_session')
    return data
  }

  const {
    data: session,            // reactive Ref<{ id: number; email: string; role: string } | undefined>
    isLoading,
    isError,
    error,
  } = useQuery(
    ['session'],             // Query key ➜ keeps cache under this key
    fetchSession,
    {
      // 1️⃣ pick only the keys that the consuming code & store need
      select: (raw) => ({
        id: raw.id,
        email: raw.email,
        role: raw.role,
      }),

      // 2️⃣ push the selected data into Pinia *once* when the query succeeds
      onSuccess: (selected) => {
        // Avoid infinite loops: update the store only if data differ
        if (selected.id !== sessionStore.id) {
          sessionStore.setSession(selected)
        }
      },

      staleTime: 60 * 1_000,            // cache for 1 minute
      retry: 1,                         // retry once on network error
      refetchOnWindowFocus: false,
    },
  )

  return { session, isLoading, isError, error }
}
```

