import { defineStore } from 'pinia'

export const useSessionStore = defineStore('session', {
  state: () => ({
    id: null as number | null,
    email: '' as string,
    role: '' as string,
  }),
  actions: {
    setSession (payload: { id: number; email: string; role: string }) {
      // One atomic patch keeps reactivity intact
      this.$patch(payload)
    },
  },
})
