import React from "react";
import FieldDropDown from "lib/hookForm/fieldDropDown";
import { ICompanyLogo } from "services/api/company/companyTypes";
import apiLoanQuery from "services/api/loan/apiLoanQuery";

interface IProps {
  /** Loan GUID that determines which logos to fetch. */
  forcePlaceLoanGuid?: string;
  /** Optional default value for the dropdown (pre-select a company logo). */
  companyGuid?: string;
}

/**
 * Renders a dropdown that allows the user to pick a company logo belonging to
 * the given loan. Uses RTK-Query to fetch the options.  Handles loading,
 * error, and empty states defensively so that the UI never crashes.
 */
export const LoanLogoDropdown: React.FC<IProps> = ({
  forcePlaceLoanGuid,
  companyGuid,
}) => {
  // Skip the query entirely when no loan GUID is provided.
  const {
    data: companyLogos,
    isLoading,
    isError,
    error,
  } = apiLoanQuery.useGetCompanyLogosInfoByLoanGuidQuery(forcePlaceLoanGuid!, {
    skip: !forcePlaceLoanGuid,
  });

  if (!forcePlaceLoanGuid) {
    // Nothing to query; render nothing to keep DOM clean and avoid misuse.
    return null;
  }

  if (isLoading) {
    return <span>Loading company logos…</span>;
  }

  if (isError) {
    console.error("LoanLogoDropdown error", error);
    return <span>Unable to load company logos.</span>;
  }

  if (!companyLogos || companyLogos.length === 0) {
    // Empty state: show a disabled dropdown so users know nothing is available.
    return (
      <FieldDropDown
        label="Company Logo"
        name="portfolioIdentifier"
        data={[]}
        placeholder="No logos available"
        disabled
        labelColSize={3}
        inputColSize={9}
      />
    );
  }

  // Transform API payload -> dropdown options.
  const logoKeyValues = companyLogos.map((logo: ICompanyLogo) => ({
    key: logo.portfolioIdentifier,
    value: logo.logoDescription || "Unnamed Logo",
  }));

  return (
    <FieldDropDown
      label="Company Logo"
      name="portfolioIdentifier"
      data={logoKeyValues}
      placeholder="Select logo"
      labelColSize={3}
      inputColSize={9}
      defaultValue={companyGuid}
      aria-label="Company logo selector"
    />
  );
};

export default LoanLogoDropdown;

