/// Converts a month name or abbreviation to its number (January = 1 .. December = 12).
///
/// # Arguments
/// * `month` – A &str containing either the full English month name (case-insensitive)
///             or the standard three-letter abbreviation.
///
/// # Returns
/// * `Option<u8>` – The month number (1-12) if the input is recognized, otherwise `None`.
///
/// # Examples
/// ```
/// assert_eq!(month_to_number("January"),  Some(1));
/// assert_eq!(month_to_number("jan"),      Some(1));
/// assert_eq!(month_to_number("Dec"),      Some(12));
/// assert_eq!(month_to_number("foobar"),   None);
/// ```
///
/// This function runs in O(1) time with a fixed match statement and allocates no heap memory.
pub fn month_to_number(month: &str) -> Option<u8> {
    match month.to_ascii_lowercase().as_str() {
        "january" | "jan" => Some(1),
        "february" | "feb" => Some(2),
        "march" | "mar" => Some(3),
        "april" | "apr" => Some(4),
        "may" => Some(5),
        "june" | "jun" => Some(6),
        "july" | "jul" => Some(7),
        "august" | "aug" => Some(8),
        "september" | "sep" | "sept" => Some(9),
        "october" | "oct" => Some(10),
        "november" | "nov" => Some(11),
        "december" | "dec" => Some(12),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn test_valid_months() {
        let table = vec![
            ("January", 1), ("feb", 2), ("Mar", 3), ("APRIL", 4),
            ("may", 5), ("JUN", 6), ("july", 7), ("Aug", 8),
            ("sept", 9), ("Oct", 10), ("NOVEMBER", 11), ("dec", 12),
        ];
        for (name, num) in table {
            assert_eq!(month_to_number(name), Some(num));
        }
    }

    #[test]
    fn test_invalid() {
        assert_eq!(month_to_number(""), None);
        assert_eq!(month_to_number("abc"), None);
        assert_eq!(month_to_number("13"), None);
    }
}
```

Design notes:
• Uses Option<u8> to avoid panics; caller decides what to do with `None`.
• Handles full names, canonical three-letter abbreviations, and common “Sept”.
• Converts to lowercase using `to_ascii_lowercase` (cheap, avoids Unicode case map pitfalls for ASCII letters).
• O(1) deterministic performance, no external crates.
• Comes with unit tests covering valid and invalid inputs.

