/**
 * Recursively searches a JSON-compatible value for a given key and returns
 * every occurrence's value together with its location inside the structure.
 *
 * @param {object|Array} jsonData – A parsed JSON object or array to search.
 * @param {string} targetKey       – The key name to look for.
 * @returns {Array<{path: Array<string|number>, value: any}>}
 *          Each item contains the array-representation of the path and the found value.
 */
function findKeyOccurrences(jsonData, targetKey) {
  if (typeof targetKey !== 'string') {
    throw new TypeError('targetKey must be a string');
  }

  const results = [];
  const seen   = new WeakSet(); // Prevent infinite loops on circular refs

  function dfs(node, path) {
    // Ignore primitives
    if (node === null || typeof node !== 'object') return;
    // Guard against circular references
    if (seen.has(node)) return;
    seen.add(node);

    if (Array.isArray(node)) {
      node.forEach((item, idx) => dfs(item, [...path, idx]));
    } else {
      Object.entries(node).forEach(([key, value]) => {
        const nextPath = [...path, key];
        if (key === targetKey) {
          results.push({ path: nextPath, value });
        }
        dfs(value, nextPath);
      });
    }
  }

  dfs(jsonData, []);
  return results;
}

// ---------------- Example ----------------
const exampleJSON = {
  a: 1,
  b: {
    a: 2,
    nested: [{ a: 3 }, { notA: 4 }]
  },
  c: [
    { a: 5, deeper: { a: 6 } },
    null
  ]
};

console.log(findKeyOccurrences(exampleJSON, 'a'));
/* Expected output (order may vary):
[
  { path: ['a'],                   value: 1 },
  { path: ['b', 'a'],              value: 2 },
  { path: ['b', 'nested', 0, 'a'], value: 3 },
  { path: ['c', 0, 'a'],           value: 5 },
  { path: ['c', 0, 'deeper', 'a'], value: 6 }
]
*/
```
Explanation:
• Depth-first traversal handles both objects and arrays.
• `WeakSet` avoids infinite recursion on cyclic structures.
• Path is an array so callers can join it using dots, brackets, or keep as-is.
• Function validates input types and throws informative errors on misuse.
• Complexity: O(N) where N is the total number of properties/elements.

