In Swift you can embed pattern matching directly inside most control-flow statements by putting the `case` keyword right after the statement’s keyword.  Below are the main techniques, each shown with compilable Swift-5 code.

1. `if case`  — one-off checks
-----------------------------------------------------
```swift
enum Message {
    case text(String)
    case location(Double, Double)
}

let msg: Message = .text("Hello!")

if case .text(let body) = msg {
    print("📩 text: \(body)")        // prints "📩 text: Hello!"
}

// Add an extra Boolean condition with a comma or `where`:
if case .text(let body) = msg, body.count > 5 {
    print("Long text (>5 chars)")
}
```

2. `guard case`  — early–exit in functions
-----------------------------------------------------
```swift
func handle(_ result: Result<String, Error>) {
    guard case .success(let data) = result else {
        print("❌ failure – bail out")
        return
    }
    print("🎉 got data: \(data)")
}
```

3. `while case` and `for case`  — iterate only matching values
-----------------------------------------------------
```swift
// while–case with an Optional stream
while case let line? = readLine() {
    print("> \(line)")
}

// for–case over a collection of enum values
let results: [Result<Int, Error>] = [.success(3), .failure(MyError()), .success(5)]
for case .failure(let err) in results {
    print("logged error: \(err)")
}
```

4. Matching Optionals, Tuples, Ranges & Types
-----------------------------------------------------
```swift
// Optionals (identical to `if let` syntactic sugar)
if case let name? = Optional("Alice") {
    print(name)
}

// Tuple pattern
let point = (x: 0, y: 0)
if case (0, 0) = point { print("Origin") }

// Numeric range
let temperature = 37.2
if case 36.5...37.5 = temperature {
    print("Normal body temperature")
}

// Type-casting pattern
import UIKit
let view: UIView = UILabel()
if case let label as UILabel = view {
    label.text = "Hello from pattern matching!"
}
```

5. Classic `switch` with `where` (still pattern-matching!)
-----------------------------------------------------
```swift
enum HTTPResponse {
    case ok(data: String, code: Int)
    case error(code: Int)
}

let response: HTTPResponse = .ok(data: "All good", code: 200)

switch response {
case .ok(let data, let code) where code == 200:
    print("✅ 200 OK: \(data)")
case .ok(_, let code):
    print("Success but not 200 – code \(code)")
case .error(let code):
    print("Server returned error code \(code)")
}
```

Common Pitfalls & Tips
-----------------------------------------------------
• Forgetting `let`/`var` after binding (`case .text(body)` will not compile).
• Using `=` instead of `==` in additional Boolean expressions.
• Omitting `return` after a failing `guard case`.
• Pattern matching works left-to-right; don’t put Boolean conditions before the pattern.
• Prefer pattern matching over manual `if`/`switch` chains for readability and exhaustiveness.

Key take-away: Insert `case` right after any control-flow keyword, write a pattern on the left of `=`, and optionally chain extra Boolean conditions. Swift’s exhaustive, type-safe patterns make control flow concise and expressive.

// Strong sample solution (no async/await, uses recursion)
function requestWithRetry(requestFn, retries = 3) {
  if (typeof requestFn !== "function") {
    throw new TypeError("requestFn must be a function returning a Promise");
  }

  return new Promise((resolve, reject) => {
    function attempt(remaining) {
      try {
        requestFn()
          .then(resolve) // succeed → bubble the value out
          .catch((err) => {
            if (remaining === 0) {
              // out of retries → reject
              reject(err);
            } else {
              attempt(remaining - 1); // recurse
            }
          });
      } catch (syncErr) {
        // requestFn threw synchronously (e.g., bad input)
        if (remaining === 0) {
          reject(syncErr);
        } else {
          attempt(remaining - 1);
        }
      }
    }

    attempt(retries);
  });
}

// Example usage:
// Suppose we have an unreliable fetch:
const unreliableFetch = () => fetch("https://example.com/data").then(r => {
  if (!r.ok) throw new Error("Bad status " + r.status);
  return r.json();
});

requestWithRetry(unreliableFetch, 3)
  .then(data => console.log("Received:", data))
  .catch(err => console.error("Failed after 3 retries:", err));

