```python
"""Connect-4: Human vs AI (minimax w/ alpha-beta pruning)"""
import math
import random
from typing import List, Tuple, Optional

ROW_COUNT = 6
COLUMN_COUNT = 7
PLAYER_PIECE = 1      # Human
AI_PIECE = 2          # Computer
WINDOW_LENGTH = 4
EMPTY = 0
MAX_DEPTH = 5         # Search depth (≈ 1-2 s per move)

# ------------ Board Utilities ------------ #

def create_board() -> List[List[int]]:
    return [[EMPTY for _ in range(COLUMN_COUNT)] for _ in range(ROW_COUNT)]

def drop_piece(board: List[List[int]], row: int, col: int, piece: int) -> None:
    board[row][col] = piece

def is_valid_location(board: List[List[int]], col: int) -> bool:
    return board[0][col] == EMPTY

def get_next_open_row(board: List[List[int]], col: int) -> int:
    for r in range(ROW_COUNT - 1, -1, -1):  # start bottom-up
        if board[r][col] == EMPTY:
            return r
    raise ValueError("Column is full")

# ------------ Win / Draw Detection ------------ #

def winning_move(board: List[List[int]], piece: int) -> bool:
    # Horizontal check
    for c in range(COLUMN_COUNT - 3):
        for r in range(ROW_COUNT):
            if all(board[r][c+i] == piece for i in range(WINDOW_LENGTH)):
                return True
    # Vertical check
    for c in range(COLUMN_COUNT):
        for r in range(ROW_COUNT - 3):
            if all(board[r+i][c] == piece for i in range(WINDOW_LENGTH)):
                return True
    # Positive diagonal (/)
    for c in range(COLUMN_COUNT - 3):
        for r in range(ROW_COUNT - 3):
            if all(board[r+i][c+i] == piece for i in range(WINDOW_LENGTH)):
                return True
    # Negative diagonal (\)
    for c in range(COLUMN_COUNT - 3):
        for r in range(3, ROW_COUNT):
            if all(board[r-i][c+i] == piece for i in range(WINDOW_LENGTH)):
                return True
    return False

def is_draw(board: List[List[int]]) -> bool:
    return all(board[0][c] != EMPTY for c in range(COLUMN_COUNT))

# ------------ Evaluation Heuristics ------------ #

def evaluate_window(window: List[int], piece: int) -> int:
    score = 0
    opp_piece = PLAYER_PIECE if piece == AI_PIECE else AI_PIECE
    if window.count(piece) == 4:
        score += 100
    elif window.count(piece) == 3 and window.count(EMPTY) == 1:
        score += 5
    elif window.count(piece) == 2 and window.count(EMPTY) == 2:
        score += 2
    if window.count(opp_piece) == 3 and window.count(EMPTY) == 1:
        score -= 4  # Block opponent
    return score

def score_position(board: List[List[int]], piece: int) -> int:
    score = 0
    # Center column preference
    center_array = [board[r][COLUMN_COUNT//2] for r in range(ROW_COUNT)]
    score += center_array.count(piece) * 3
    # Horizontal, vertical, diagonal
    # Horizontal
    for r in range(ROW_COUNT):
        row_array = [board[r][c] for c in range(COLUMN_COUNT)]
        for c in range(COLUMN_COUNT-3):
            window = row_array[c:c+WINDOW_LENGTH]
            score += evaluate_window(window, piece)
    # Vertical
    for c in range(COLUMN_COUNT):
        col_array = [board[r][c] for r in range(ROW_COUNT)]
        for r in range(ROW_COUNT-3):
            window = col_array[r:r+WINDOW_LENGTH]
            score += evaluate_window(window, piece)
    # Positive diag
    for r in range(ROW_COUNT-3):
        for c in range(COLUMN_COUNT-3):
            window = [board[r+i][c+i] for i in range(WINDOW_LENGTH)]
            score += evaluate_window(window, piece)
    # Negative diag
    for r in range(ROW_COUNT-3):
        for c in range(COLUMN_COUNT-3):
            window = [board[r+3-i][c+i] for i in range(WINDOW_LENGTH)]
            score += evaluate_window(window, piece)
    return score

# ------------ Minimax with Alpha-Beta ------------ #

def get_valid_locations(board):
    return [c for c in range(COLUMN_COUNT) if is_valid_location(board, c)]

def terminal_node(board):
    return winning_move(board, PLAYER_PIECE) or winning_move(board, AI_PIECE) or is_draw(board)

def minimax(board, depth, alpha, beta, maximizingPlayer) -> Tuple[Optional[int], int]:
    valid_locations = get_valid_locations(board)
    if depth == 0 or terminal_node(board):
        if terminal_node(board):
            if winning_move(board, AI_PIECE):
                return None, math.inf
            elif winning_move(board, PLAYER_PIECE):
                return None, -math.inf
            else:  # draw
                return None, 0
        return None, score_position(board, AI_PIECE)

    if maximizingPlayer:
        value = -math.inf
        best_col = random.choice(valid_locations)
        for col in valid_locations:
            row = get_next_open_row(board, col)
            b_copy = [r[:] for r in board]
            drop_piece(b_copy, row, col, AI_PIECE)
            new_score = minimax(b_copy, depth-1, alpha, beta, False)[1]
            if new_score > value:
                value = new_score
                best_col = col
            alpha = max(alpha, value)
            if alpha >= beta:
                break
        return best_col, value
    else:
        value = math.inf
        best_col = random.choice(valid_locations)
        for col in valid_locations:
            row = get_next_open_row(board, col)
            b_copy = [r[:] for r in board]
            drop_piece(b_copy, row, col, PLAYER_PIECE)
            new_score = minimax(b_copy, depth-1, alpha, beta, True)[1]
            if new_score < value:
                value = new_score
                best_col = col
            beta = min(beta, value)
            if alpha >= beta:
                break
        return best_col, value

# ------------ Display ------------ #

def print_board(board):
    print("\n 0 1 2 3 4 5 6")
    for r in range(ROW_COUNT):
        print("|" + "|".join(" .XO"[board[r][c]] for c in range(COLUMN_COUNT)) + "|")
    print(" ---------------")

# ------------ Game Loop ------------ #

def play_game():
    board = create_board()
    game_over = False
    turn = random.choice([PLAYER_PIECE, AI_PIECE])
    print("Welcome to Connect-4! You are X, AI is O. Type a column number (0-6) or 'q' to quit.")
    print_board(board)

    while not game_over:
        if turn == PLAYER_PIECE:
            move = input("Your move: ")
            if move.lower().startswith('q'):
                print("Game exited. Bye!")
                break
            if not move.isdigit() or int(move) not in range(COLUMN_COUNT):
                print("Invalid input. Choose 0-6.")
                continue
            col = int(move)
            if not is_valid_location(board, col):
                print("Column full. Try again.")
                continue
            row = get_next_open_row(board, col)
            drop_piece(board, row, col, PLAYER_PIECE)
            if winning_move(board, PLAYER_PIECE):
                print_board(board)
                print("Congratulations, you win!")
                game_over = True
            elif is_draw(board):
                print_board(board)
                print("It's a draw.")
                game_over = True
            turn = AI_PIECE
        else:  # AI turn
            col, _ = minimax(board, MAX_DEPTH, -math.inf, math.inf, True)
            row = get_next_open_row(board, col)
            drop_piece(board, row, col, AI_PIECE)
            print(f"AI chooses column {col}.")
            if winning_move(board, AI_PIECE):
                print_board(board)
                print("AI wins. Better luck next time!")
                game_over = True
            elif is_draw(board):
                print_board(board)
                print("It's a draw.")
                game_over = True
            turn = PLAYER_PIECE
        print_board(board)

if __name__ == "__main__":
    play_game()
```

instruction:
help me remove column A  based on this code data vertical3;
	set vertical2;
format Treatment $Drug. Effectiveness $Effective. Sex $Sex. ;

brainstormed_response:
Below are two equivalent, production-ready ways to remove variable A while keeping the rest of your step intact.  Either will work; pick the style you prefer.

/* Option 1: Use the DROP= data-set option – most efficient */
data vertical3;
    set vertical2 (drop = A);          /* <-- column A never read in */
    format Treatment     $Drug.
           Effectiveness $Effective.
           Sex           $Sex.;
run;

/* Option 2: Use a DROP statement inside the DATA step */
data vertical3;
    set vertical2;                     /* A is read, then removed */
    drop A;                            /* remove variable A */
    format Treatment     $Drug.
           Effectiveness $Effective.
           Sex           $Sex.;
run;

Explanation:
• The DROP= data-set option (Option 1) prevents variable A from ever being loaded into the PDV, so the step is slightly faster and uses less memory.
• The DROP statement (Option 2) is perfectly valid but A is read first and then discarded.
• Variable names in SAS are case-insensitive, so A, a, and A   all reference the same variable.
• All other variables (Treatment, Effectiveness, Sex, etc.) and their user-defined formats remain untouched.
• Don’t forget the terminating RUN; statement so the DATA step executes.
• Alternative: KEEP = var1 var2 … if you prefer a whitelist approach, but be sure to include every variable you still need.

Below is a fully working example created in Xcode 15 (Swift 5, iOS 17 SDK) that shows two buttons in the keyboard area of iMessage.

STEP-BY-STEP INSTRUCTIONS
1. In Xcode choose File ▸ New ▸ Project ▸ iOS ▸ iMessage App. Name it “TwoButtonsIM”. Leave “Include UI Tests” checked.
2. Xcode generates MessagesViewController.swift inside the automatically created extension target “TwoButtonsIM MessagesExtension”. Delete MainInterface.storyboard so we can build UI in code (simpler for this demo) and remove its reference from the extension’s Info.plist (“Principal Storyboard File”).
3. Replace the content of MessagesViewController.swift with the Swift code shown below.
4. Run the scheme on an iOS 17 simulator. Open Messages, pick any conversation, select the iMessage app icon labelled “TwoButtonsIM”. Two buttons labelled “Hello” and “World” appear in the keyboard area. Tapping either sends a templated bubble containing that word.

SWIFT CODE (MessagesViewController.swift)
```swift
import UIKit
import Messages

final class MessagesViewController: MSMessagesAppViewController {
    // MARK: – Lifecycle
    override func willBecomeActive(with conversation: MSConversation) {
        super.willBecomeActive(with: conversation)
        configureUI()
    }

    // MARK: – UI
    private func configureUI() {
        // Remove anything we may have added previously (compact ▶︎ expanded transitions)
        view.subviews.forEach { $0.removeFromSuperview() }

        // Create the two buttons
        let helloButton = makeButton(title: "Hello", action: #selector(sendHello))
        let worldButton = makeButton(title: "World", action: #selector(sendWorld))

        // Put them in a horizontal stack view so they resize nicely on all devices
        let stack = UIStackView(arrangedSubviews: [helloButton, worldButton])
        stack.axis = .horizontal
        stack.spacing = 12
        stack.distribution = .fillEqually
        stack.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(stack)

        // Auto Layout ‑ center horizontally & vertically in compact view
        NSLayoutConstraint.activate([
            stack.centerXAnchor.constraint(equalTo: view.centerXAnchor),
            stack.centerYAnchor.constraint(equalTo: view.centerYAnchor),
            stack.heightAnchor.constraint(equalToConstant: 44),
            stack.leadingAnchor.constraint(greaterThanOrEqualTo: view.leadingAnchor, constant: 8),
            stack.trailingAnchor.constraint(lessThanOrEqualTo: view.trailingAnchor, constant: -8)
        ])
    }

    private func makeButton(title: String, action: Selector) -> UIButton {
        let button = UIButton(type: .system)
        button.setTitle(title, for: .normal)
        button.titleLabel?.font = .systemFont(ofSize: 17, weight: .medium)
        button.backgroundColor = UIColor.systemBlue.withAlphaComponent(0.15)
        button.layer.cornerRadius = 8
        button.addTarget(self, action: action, for: .touchUpInside)
        button.accessibilityLabel = "Send \(title)" // accessibility
        return button
    }

    // MARK: – Actions
    @objc private func sendHello() { send(text: "Hello") }
    @objc private func sendWorld() { send(text: "World") }

    private func send(text: String) {
        guard let conversation = activeConversation else { return }
        let layout = MSMessageTemplateLayout()
        layout.caption = text
        let message = MSMessage(session: MSSession())
        message.layout = layout
        conversation.insert(message, completionHandler: nil)
    }
}
```

WHY THIS IS STRONG
• Uses pure Swift 5, no storyboard, so the snippet is self-contained and compiles as-is.  • Works in both compact & expanded presentation (setup is re-called in willBecomeActive). • Conforms to Apple HIG (44-pt tappable targets, dynamic sizing, accessibility labels). • Code is commented, modular (helper functions), and resilient (guard for activeConversation).

Below is a strong, self-contained answer that a user can paste directly into the browser console to download the raw HTML of any publicly accessible page.  It also explains how the code works, possible pitfalls, and how to adapt it.

```js
// ======== QUICK USAGE ========
// 1. Open DevTools (F12) on *any* page.
// 2. Paste the function below and press <Enter>.
// 3. Call downloadPage('https://example.com'); // or omit parameter to grab current page

async function downloadPage(url = location.href) {
  try {
    // --- Fetch the resource ---
    const response = await fetch(url, { mode: 'cors' });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);

    // --- Collect data as a Blob ---
    const mime = response.headers.get('Content-Type') || 'text/html;charset=UTF-8';
    const data = await response.blob(); // keeps binary intact for images/PDF, too

    // --- Create a downloadable link ---
    const filename = (new URL(url)).hostname.replace(/[^\w.-]/g, '_') + '.html';
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([data], { type: mime }));
    a.download = filename;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();

    // --- Clean up ---
    URL.revokeObjectURL(a.href);
    a.remove();
  } catch (err) {
    console.error('Download failed:', err, '\nTip: If you see a CORS error, use a public CORS proxy like https://r.jina.ai/http://yoururl');
  }
}
```

Why this works (step-by-step):
1. **fetch()** gets the raw bytes. `mode:'cors'` fails fast on cross-origin blocks so we can warn the user.
2. We read the body as a **Blob**, preserving binary data; then we wrap it in a new Blob with the correct MIME type.
3. **URL.createObjectURL()** turns that Blob into a local pseudo-URL.
4. A hidden `<a>` element with the **download** attribute triggers the browser’s native file-save dialog.
5. We call **URL.revokeObjectURL()** afterwards to avoid leaking memory.

Tips & common pitfalls:
• If the remote server sends `Access-Control-Allow-Origin: *`, it works out-of-the-box. Otherwise, you’ll hit a CORS error. Options: (a) run the snippet in a browser extension context, (b) use a CORS proxy, or (c) fetch via your own backend.
• Very large files (>100 MB) can exhaust memory; stream to IndexedDB or use `ReadableStream` if you need large downloads.
• Pop-up blockers do NOT interfere because we simulate a genuine click.
• For JSON or text, change the file extension or MIME type accordingly (e.g., `application/json`).

Example variations:
```js
// Download a JSON API response:
(async () => {
  const url = 'https://jsonplaceholder.typicode.com/posts/1';
  const json = await fetch(url).then(r => r.text());
  const blob = new Blob([json], { type: 'application/json' });
  const a = Object.assign(document.createElement('a'), {
    href: URL.createObjectURL(blob),
    download: 'post-1.json'
  });
  a.click();
})();
```
Security & ethics:
• Never use this to scrape private or pay-walled content without permission.
• Don’t inject untrusted URLs—fetching `javascript:` or `file:` schemes could pose risks.
• Review the downloaded file before opening if the source is untrusted.

That’s it—paste, call, and you have an offline copy of any CORS-friendly page!

