/*
 * Example: .NET 6 console app that posts JSON to https://example.com/api/endpoint
 * A client certificate (client.pfx) with password is attached to the request.
 * NOTE: Replace certPath, certPassword, and request URI with real values in production.
 */

using System;
using System.Net.Http;
using System.Security.Cryptography.X509Certificates;
using System.Threading.Tasks;

namespace ClientCertPostExample
{
    internal class Program
    {
        // C# 9 / .NET 5+ allows async Main
        private static async Task Main()
        {
            const string certPath = "client.pfx";        // <-- path to your .pfx file
            const string certPassword = "p@ssw0rd";      // <-- NEVER hard-code in production!

            // Load the certificate (must include private key)
            var cert = new X509Certificate2(
                certPath,
                certPassword,
                X509KeyStorageFlags.MachineKeySet | X509KeyStorageFlags.EphemeralKeySet);

            // Create a handler and attach the client certificate
            var handler = new HttpClientHandler();
            handler.ClientCertificates.Add(cert);
            handler.SslProtocols = System.Security.Authentication.SslProtocols.Tls12; // optional but recommended

            using var client = new HttpClient(handler) { BaseAddress = new Uri("https://example.com") };

            // JSON body to send
            using var content = new StringContent("{ \"data\": \"value\" }", System.Text.Encoding.UTF8, "application/json");

            try
            {
                HttpResponseMessage response = await client.PostAsync("/api/endpoint", content);
                response.EnsureSuccessStatusCode();

                string responseBody = await response.Content.ReadAsStringAsync();
                Console.WriteLine("Server responded with:\n" + responseBody);
            }
            catch (HttpRequestException ex)
            {
                Console.Error.WriteLine($"Request failed: {ex.Message}");
            }
        }
    }
}

